3	/// One damaged item reported in an incident.
4	pub struct Damage {
5	    pub item_type: String,
6	    pub amount: i64,
7	}
8	
9	/// A damage report filed against an existing policy.
10	pub struct Incident {
11	    pub damages: Vec<Damage>,
12	}
13	
14	/// What the MHPCO settles on a claim: the payout and the cap left on the
15	/// policy afterwards.
16	pub struct ClaimResult {
17	    pub payout: u64,
18	    pub remaining_cap: u64,
19	}
20	
21	/// The single customer a scenario is quoted for.
22	pub struct Customer {
23	    pub years_with_mhpco: u32,
24	}
25	
26	pub struct Item {
27	    pub item_type: String,
28	    pub material: String,
29	    pub enchantment: u32,
30	    pub cursed: bool,
31	}
32	
33	const PROCESSING_FEE: u64 = 5;
34	const DEDUCTIBLE_PER_DAMAGE: u64 = 100;
35	const CAP_MULTIPLE_OF_INSURANCE_SUM: u64 = 2;
36	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL: u32 = 8;
37	const HALF_REIMBURSEMENT_PERCENT: u64 = 50;
38	
39	const SWORD_INSURANCE_VALUE: u64 = 1000;
40	const AMULET_INSURANCE_VALUE: u64 = 600;
41	const COMPONENT_INSURANCE_VALUE: u64 = 250;
42	const SWORD_BASE_PREMIUM: u64 = 100;
43	const AMULET_BASE_PREMIUM: u64 = 60;
44	const STAFF_BASE_PREMIUM: u64 = 80;
45	const POTION_BASE_PREMIUM: u64 = 40;
46	const COMPONENT_BASE_PREMIUM: u64 = 25;
47	const COMPONENT_BLOCK_BASE_PREMIUM: u64 = 60;
48	const COMPONENT_BLOCK_SIZE: usize = 3;
49	const CURSE_SURCHARGE_PERCENT: u64 = 50;
50	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT: u64 = 30;
51	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
52	const FIRST_INSURANCE_SURCHARGE_PERCENT: u64 = 10;
53	const LOYALTY_DISCOUNT_PERCENT: u64 = 20;
54	const LOYALTY_YEARS: u32 = 2;
55	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT: u64 = 15;
56	
57	/// Components, such as runes and moonstones, are the parts the MHPCO insures
58	/// alongside main items and the only items the building-block offer covers.
59	fn is_component(item: &Item) -> bool {
60	    matches!(item.item_type.as_str(), "rune" | "moonstone")
61	}
62	
63	/// The MHPCO price list: the base premium the catalogue lists for one item.
64	fn base_premium(item: &Item) -> u64 {
65	    if is_component(item) {
66	        return COMPONENT_BASE_PREMIUM;
67	    }
68	    match item.item_type.as_str() {
69	        "amulet" => AMULET_BASE_PREMIUM,
70	        "staff" => STAFF_BASE_PREMIUM,
71	        "potion" => POTION_BASE_PREMIUM,
72	        _ => SWORD_BASE_PREMIUM,
73	    }
74	}
75	
76	/// The building-block offer is reserved for a group of exactly 3 alike
77	/// components; a larger group does not qualify, it is priced per component.
78	fn qualifies_as_building_block(alike_component_count: usize) -> bool {
79	    alike_component_count == COMPONENT_BLOCK_SIZE
80	}
81	
82	/// The price the MHPCO charges for one group of alike components: the
83	/// building-block offer when the group qualifies, otherwise per component.
84	fn component_group_base_premium(count: usize) -> u64 {
85	    if qualifies_as_building_block(count) {
86	        COMPONENT_BLOCK_BASE_PREMIUM
87	    } else {
88	        count as u64 * COMPONENT_BASE_PREMIUM
89	    }
90	}
91	
92	/// Two components are "alike" when they share this key. For the MHPCO,
93	/// alike means the very same catalogue type: a rune and a moonstone are
94	/// never alike, so mixed component types form no building block.
95	fn alike_group_key(item: &Item) -> &str {
96	    &item.item_type
97	}
98	
99	/// The policy base premium: the sum of all insured items' base premiums,
100	/// with alike components priced per group so a block can be recognised.
101	fn policy_base_premium(items: &[Item]) -> u64 {
102	    let mut main_items_total = 0;
103	    let mut alike_component_counts: BTreeMap<&str, usize> = BTreeMap::new();
104	    for item in items {
105	        if is_component(item) {
106	            *alike_component_counts.entry(alike_group_key(item)).or_insert(0) += 1;
107	        } else {
108	            main_items_total += base_premium(item);
109	        }
110	    }
111	
112	    main_items_total
113	        + alike_component_counts
114	            .values()
115	            .map(|count| component_group_base_premium(*count))
116	            .sum::<u64>()
117	}
118	
119	/// Who owes an amount, which is what decides the direction the MHPCO rounds it.
120	#[derive(Clone, Copy)]
121	enum Debtor {
122	    Customer,
123	    Mhpco,
124	}
125	
126	/// Every amount is rounded to whole G in the MHPCO's favor. That one rule
127	/// settles the direction by itself once it is known who owes whom: an amount
128	/// the customer owes is rounded up, an amount the office owes is rounded down.
129	/// Intermediate amounts stay fractional; only the final amount is rounded.
130	fn rounded_in_mhpco_favor(amount: f64, owed_by: Debtor) -> u64 {
131	    match owed_by {
132	        Debtor::Customer => amount.ceil() as u64,
133	        Debtor::Mhpco => amount.floor() as u64,
134	    }
135	}
136	
137	/// A policy-wide modifier is measured against the policy base premium, the
138	/// sum of all item base premiums, never against a single item.
139	fn percent_of_policy_base(policy_base_premium: f64, percent: u64) -> f64 {
140	    policy_base_premium * percent as f64 / 100.0
141	}
142	
143	/// Every item in a quote is treated as a first insurance, so the initial
144	/// assessment surcharge is charged on the whole policy base premium.
145	fn first_insurance_surcharge(policy_base_premium: f64) -> f64 {
146	    percent_of_policy_base(policy_base_premium, FIRST_INSURANCE_SURCHARGE_PERCENT)
147	}
148	
149	/// The MHPCO charges a high-enchantment risk surcharge on items it considers
150	/// highly enchanted. This is the premium-side threshold; the claim-side
151	/// reimbursement clause judges enchantment by its own, stricter threshold.
152	fn is_highly_enchanted(item: &Item) -> bool {
153	    item.enchantment >= HIGH_ENCHANTMENT_LEVEL
154	}
155	
156	/// An item-specific risk surcharge is charged on the base premium of the
157	/// affected item, never on the policy total.
158	fn risk_surcharge_on_base_premium(item: &Item, surcharge_percent: u64) -> f64 {
159	    base_premium(item) as f64 * surcharge_percent as f64 / 100.0
160	}
161	
162	/// The risk surcharge one item carries. Risks the MHPCO recognises stack: an
163	/// item that brings two of them is surcharged for each.
164	fn item_risk_surcharge(item: &Item) -> f64 {
165	    let mut surcharge = 0.0;
166	    if item.cursed {
167	        surcharge += risk_surcharge_on_base_premium(item, CURSE_SURCHARGE_PERCENT);
168	    }
169	    if is_highly_enchanted(item) {
170	        surcharge += risk_surcharge_on_base_premium(item, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
171	    }
172	    surcharge
173	}
174	
175	/// Item-specific modifiers apply to the base premium of the affected item,
176	/// never to the policy total, so the policy owes the sum of the items' own
177	/// risk surcharges.
178	fn item_risk_surcharges(items: &[Item]) -> f64 {
179	    items.iter().map(item_risk_surcharge).sum()
180	}
181	
182	/// A long-standing customer, with at least two years of business with the
183	/// MHPCO, has earned the loyalty discount.
184	fn is_long_standing(customer: &Customer) -> bool {
185	    customer.years_with_mhpco >= LOYALTY_YEARS
186	}
187	
188	/// The loyalty discount is a policy-wide modifier, so it is measured against
189	/// the policy base premium.
190	fn loyalty_discount(customer: &Customer, policy_base_premium: f64) -> f64 {
191	    if is_long_standing(customer) {
192	        percent_of_policy_base(policy_base_premium, LOYALTY_DISCOUNT_PERCENT)
193	    } else {
194	        0.0
195	    }
196	}
197	
198	/// A contract is a follow-up when the customer already holds at least one
199	/// other contract with the MHPCO; the customer's very first is not.
200	fn is_follow_up_contract(contracts_already_held: u32) -> bool {
201	    contracts_already_held > 0
202	}
203	
204	/// Every contract after the customer's first earns the follow-up discount. It
205	/// is a policy-wide modifier, so it is measured against the policy base premium.
206	fn follow_up_contract_discount(contracts_already_held: u32, policy_base_premium: f64) -> f64 {
207	    if is_follow_up_contract(contracts_already_held) {
208	        percent_of_policy_base(policy_base_premium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)
209	    } else {
210	        0.0
211	    }
212	}
213	
214	/// What the customer's standing with the MHPCO adds to or takes off the policy
215	/// base premium: the net of every policy-wide surcharge and discount. Positive
216	/// amounts raise the premium, negative amounts lower it.
217	fn policy_wide_modifiers(
218	    customer: &Customer,
219	    contracts_already_held: u32,
220	    policy_base_premium: f64,
221	) -> f64 {
222	    first_insurance_surcharge(policy_base_premium)
223	        - loyalty_discount(customer, policy_base_premium)
224	        - follow_up_contract_discount(contracts_already_held, policy_base_premium)
225	}
226	
227	/// The premium the policy earns before the processing fee: the policy base
228	/// premium, plus what the items' own risks cost, plus what the customer's
229	/// standing adjusts.
230	fn modified_policy_premium(
231	    customer: &Customer,
232	    contracts_already_held: u32,
233	    items: &[Item],
234	) -> f64 {
235	    let policy_base_premium = policy_base_premium(items) as f64;
236	    policy_base_premium
237	        + item_risk_surcharges(items)
238	        + policy_wide_modifiers(customer, contracts_already_held, policy_base_premium)
239	}
240	
241	/// The MHPCO adds its processing fee to every premium at the very end, after
242	/// every surcharge and discount has been settled.
243	pub fn quote_premium(
244	    customer: &Customer,
245	    contracts_already_held: u32,
246	    items: &[Item],
247	) -> u64 {
248	    rounded_in_mhpco_favor(
249	        modified_policy_premium(customer, contracts_already_held, items) + PROCESSING_FEE as f64,
250	        Debtor::Customer,
251	    )
252	}
253	
254	/// Damage to a very highly enchanted item is reimbursed at only half the
255	/// damage amount. This claim-side threshold is deliberately stricter than, and
256	/// separate from, the premium-side high-enchantment risk surcharge: an item can
257	/// be enchanted enough to cost more to insure yet not enough to be halved.
258	fn is_reimbursed_by_half(item: &Item) -> bool {
259	    item.enchantment >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
260	}
261	
262	/// How much of a reported damage the MHPCO's reimbursement clauses cover,
263	/// before the deductible is taken off. Full reimbursement is the MHPCO's
264	/// standing position: it is both what an item with no clause receives and what
265	/// the dragon-material clause prescribes, so that clause asks for no share of
266	/// its own. Only the halving clause departs from full reimbursement, and it
267	/// wins wherever it applies.
268	fn covered_damage(damaged_item: &Item, damage: &Damage) -> f64 {
269	    if is_reimbursed_by_half(damaged_item) {
270	        damage.amount as f64 * HALF_REIMBURSEMENT_PERCENT as f64 / 100.0
271	    } else {
272	        damage.amount as f64
273	    }
274	}
275	
276	/// The deductible applies per damage event, after the reimbursement clauses.
277	fn reimbursement_for(damaged_item: &Item, damage: &Damage) -> f64 {
278	    (covered_damage(damaged_item, damage) - DEDUCTIBLE_PER_DAMAGE as f64).max(0.0)
279	}
280	
281	/// Which insured item a reported damage refers to. A damage names only a
282	/// catalogue type, so the policy is searched for an item of that type; the
283	/// reimbursement clauses are judged against the item found here, not the report.
284	fn insured_item_for<'a>(items: &'a [Item], damage: &Damage) -> &'a Item {
285	    items
286	        .iter()
287	        .find(|item| item.item_type == damage.item_type)
288	        .expect("the damaged item is insured by this policy")
289	}
290	
291	/// What the MHPCO owes for an incident filed against a policy: the sum of the
292	/// reimbursements its damages earn, rounded in the office's favor at the end.
293	pub fn claim_payout(items: &[Item], incident: &Incident) -> u64 {
294	    let total: f64 = incident
295	        .damages
296	        .iter()
297	        .map(|damage| reimbursement_for(insured_item_for(items, damage), damage))
298	        .sum();
299	    rounded_in_mhpco_favor(total, Debtor::Mhpco)
300	}
301	
302	/// The MHPCO price list also lists what each item is insured for.
303	fn insurance_value(item: &Item) -> u64 {
304	    if is_component(item) {
305	        return COMPONENT_INSURANCE_VALUE;
306	    }
307	    match item.item_type.as_str() {
308	        "amulet" => AMULET_INSURANCE_VALUE,
309	        _ => SWORD_INSURANCE_VALUE,
310	    }
311	}
312	
313	/// The insurance sum of a policy is the sum of its items' insurance values.
314	fn insurance_sum(items: &[Item]) -> u64 {
315	    items.iter().map(insurance_value).sum()
316	}
317	
318	/// The total payout per policy is capped at twice the insurance sum.
319	fn policy_cap(items: &[Item]) -> u64 {
320	    CAP_MULTIPLE_OF_INSURANCE_SUM * insurance_sum(items)
321	}
322	
323	pub fn claim(items: &[Item], incident: &Incident) -> ClaimResult {
324	    let cap = policy_cap(items);
325	    let payout = claim_payout(items, incident).min(cap);
326	    ClaimResult {
327	        payout,
328	        remaining_cap: cap - payout,
329	    }
330	}
