    insurance_value: SWORD_INSURANCE_VALUE,
    base_premium: SWORD_BASE_PREMIUM,
};
const AMULET_ROW: PriceListRow = PriceListRow {
    insurance_value: AMULET_INSURANCE_VALUE,
    base_premium: AMULET_BASE_PREMIUM,
};
