    insurance_value: COMPONENT_INSURANCE_VALUE,
    base_premium: COMPONENT_BASE_PREMIUM,
};

/// The row the MHPCO price list lists an item under. Every component is
/// catalogued under the one component row, whatever kind it is; a type the
/// office has no row of its own for is priced as a sword.
fn price_list_row(item: &Item) -> PriceListRow {
    if is_component(item) {
        return COMPONENT_ROW;
    }
    match item.item_type.as_str() {
        "amulet" => AMULET_ROW,
        _ => SWORD_ROW,
    }
